+package com.example.customers.domain;
+
+import java.io.Serializable;
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+
+/** Immutable criteria shared by the backend's page and count queries. */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) implements Serializable {
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        name = name == null ? "" : name;
+        statuses = Set.copyOf(statuses);
+    }
+
+    public List<String> nameTerms() {
+        return Arrays.stream(fold(name).split("(?U)\\s+"))
+                .filter(term -> !term.isEmpty())
+                .toList();
+    }
+
+    public boolean matches(Customer customer, List<String> terms) {
+        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
+            return false;
+        }
+        String firstName = fold(customer.firstName());
+        String lastName = fold(customer.lastName());
+        return terms.stream().allMatch(term -> firstName.contains(term) || lastName.contains(term));
+    }
+
+    private static String fold(String text) {
+        return Normalizer.normalize(text, Normalizer.Form.NFD)
+                .replaceAll("\\p{M}+", "")
+                .toLowerCase(Locale.ROOT);
+    }
+}
